import { inflateRawSync } from 'node:zlib';
import { afterAll, describe, expect, it } from 'vitest';
import { canvas, fx } from '../lib/canvas';
import { digestOf } from '../lib/harness';
import { ids, runNode, runOk } from './support/adminGroup';
import type { Json } from '../lib/n8n';
import { loadState } from '../lib/state';

/**
 * Resource: accountReport. Reports are generated by Canvas' job workers, so the
 * tests start real reports, wait for them and inspect the generated files.
 */


/** Fetch a report file the way a workflow would (Canvas redirects to the stored file). */
async function download(url: string): Promise<Buffer> {
	const token = loadState().canvas.tokens.admin;
	const res = await fetch(url, { headers: { authorization: `Bearer ${token}` } });
	if (!res.ok) throw new Error(`download ${url} -> ${res.status}`);
	return Buffer.from(await res.arrayBuffer());
}

/** Minimal zip reader (stored and deflated entries), enough for Canvas' multi-file reports. */
function unzip(zip: Buffer): Record<string, string> {
	const files: Record<string, string> = {};
	let offset = zip.lastIndexOf(Buffer.from([0x50, 0x4b, 0x05, 0x06]));
	if (offset < 0) throw new Error('not a zip file');
	const entries = zip.readUInt16LE(offset + 10);
	offset = zip.readUInt32LE(offset + 16);
	for (let i = 0; i < entries; i++) {
		const method = zip.readUInt16LE(offset + 10);
		const compressedSize = zip.readUInt32LE(offset + 20);
		const nameLength = zip.readUInt16LE(offset + 28);
		const extraLength = zip.readUInt16LE(offset + 30);
		const commentLength = zip.readUInt16LE(offset + 32);
		const localOffset = zip.readUInt32LE(offset + 42);
		const name = zip.toString('utf8', offset + 46, offset + 46 + nameLength);
		const dataStart = localOffset + 30 + zip.readUInt16LE(localOffset + 26) + zip.readUInt16LE(localOffset + 28);
		const data = zip.subarray(dataStart, dataStart + compressedSize);
		files[name] = (method === 0 ? data : inflateRawSync(data)).toString('utf8');
		offset += 46 + nameLength + extraLength + commentLength;
	}
	return files;
}

/** CSV rows with quoted fields (SIS IDs in the seed contain commas and quotes). */
function parseCsv(text: string): string[][] {
	const rows: string[][] = [];
	let row: string[] = [];
	let field = '';
	let quoted = false;
	for (let i = 0; i < text.length; i++) {
		const ch = text[i];
		if (quoted) {
			if (ch === '"' && text[i + 1] === '"') {
				field += '"';
				i++;
			} else if (ch === '"') {
				quoted = false;
			} else {
				field += ch;
			}
		} else if (ch === '"') {
			quoted = true;
		} else if (ch === ',') {
			row.push(field);
			field = '';
		} else if (ch === '\n') {
			row.push(field);
			rows.push(row);
			row = [];
			field = '';
		} else if (ch !== '\r') {
			field += ch;
		}
	}
	if (field !== '' || row.length > 0) {
		row.push(field);
		rows.push(row);
	}
	return rows;
}

describe('accountReport', () => {
	const root = fx('accountId');
	const sub = fx('subAccountId');
	const createdReports: Array<{ account: string; type: string; id: string }> = [];

	const remember = (account: string, report: Json): string => {
		const id = String(report.id);
		createdReports.push({ account, type: String(report.report), id });
		return id;
	};

	/** Poll through the node's Get operation until the report has finished. */
	async function waitForReport(account: string, type: string, id: string): Promise<Json> {
		for (let attempt = 0; attempt < 60; attempt++) {
			const [report] = await runOk({
				resource: 'accountReport',
				operation: 'get',
				params: { accountId: account, reportType: type, reportId: id },
			});
			if (['complete', 'error', 'aborted'].includes(String(report.status))) return report;
			await new Promise((resolve) => setTimeout(resolve, 2000));
		}
		throw new Error(`report ${type}/${id} did not finish`);
	}

	afterAll(async () => {
		for (const report of createdReports) {
			await canvas().request('DELETE', `/api/v1/accounts/${report.account}/reports/${report.type}/${report.id}`);
		}
	});

	// ------------------------------------------------------------ listAvailable

	it('listAvailable: lists every report type with its parameters', async () => {
		const expected = await canvas().get<Json[]>(`/api/v1/accounts/${root}/reports`);
		const listed = await runOk({ resource: 'accountReport', operation: 'listAvailable', params: { accountId: root } });
		expect(listed.map((r) => r.report).sort()).toEqual(expected.map((r) => r.report).sort());
		expect(listed.length).toBeGreaterThan(10);
		const provisioning = listed.find((r) => r.report === 'provisioning_csv')!;
		expect(Object.keys(provisioning.parameters as Json)).toEqual(
			expect.arrayContaining(['enrollment_term_id', 'users', 'courses', 'sections', 'enrollments', 'enrollment_filter']),
		);
		expect(provisioning.description_html).toBeUndefined();
	});

	it('listAvailable: includes the HTML description and parameter form, also for a sub-account by SIS ID', async () => {
		const listed = await runOk({
			resource: 'accountReport',
			operation: 'listAvailable',
			params: {
				accountId: `sis_account_id:${fx('subAccountSisId')}`,
				options: { include: ['description_html', 'parameters_html'] },
			},
		});
		const provisioning = listed.find((r) => r.report === 'provisioning_csv')!;
		expect(String(provisioning.description_html)).toContain('<');
		expect(String(provisioning.parameters_html)).toContain('<');
	});

	it('listAvailable: a teacher is refused', async () => {
		const result = await runNode({
			resource: 'accountReport',
			operation: 'listAvailable',
			persona: 'teacher',
			params: { accountId: root, errorHandling: { onError: 'continueWithError' } },
		});
		expect(result.success).toEqual([]);
		expect(result.error[0].errorType).toBe('FORBIDDEN');
	});

	// ------------------------------------------------------------------ create

	it('create: provisioning report with every file switched on; the generated zip holds each file', async () => {
		const [report] = await runOk({
			resource: 'accountReport',
			operation: 'create',
			params: {
				accountId: sub,
				reportType: 'provisioning_csv',
				additionalFields: {
					accounts: true,
					admins: true,
					courses: true,
					created_by_sis: false,
					enrollment_filter: ['StudentEnrollment', 'TeacherEnrollment'],
					enrollment_states: ['active', 'invited'],
					enrollment_term_id: fx('termId'),
					enrollments: true,
					group_categories: true,
					group_membership: true,
					groups: true,
					include_deleted: true,
					sections: true,
					skip_message: true,
					terms: true,
					user_observers: true,
					users: true,
					xlist: true,
				},
			},
		});
		const id = remember(sub, report);
		expect(report).toMatchObject({ report: 'provisioning_csv' });
		expect(['created', 'running']).toContain(report.status);

		const stored = await canvas().get<Json>(`/api/v1/accounts/${sub}/reports/provisioning_csv/${id}`);
		expect(stored.parameters).toMatchObject({
			accounts: true,
			admins: true,
			courses: true,
			created_by_sis: false,
			enrollment_filter: ['StudentEnrollment', 'TeacherEnrollment'],
			enrollment_states: ['active', 'invited'],
			enrollment_term_id: fx('termId'),
			enrollments: true,
			group_categories: true,
			group_membership: true,
			groups: true,
			include_deleted: true,
			sections: true,
			skip_message: true,
			terms: true,
			user_observers: true,
			users: true,
			xlist: true,
		});

		const finished = await waitForReport(sub, 'provisioning_csv', id);
		expect(finished.status).toBe('complete');
		expect(finished.progress).toBe(100);
		expect(String(finished.file_url)).toContain(`/accounts/${sub}/files/`);
		const attachment = finished.attachment as Json;
		expect(String(attachment.filename)).toMatch(/\.zip$/);

		const files = unzip(await download(String(attachment.url)));
		expect(Object.keys(files).sort()).toEqual(
			[
				'accounts.csv',
				'admins.csv',
				'courses.csv',
				'enrollments.csv',
				'group_categories.csv',
				'group_membership.csv',
				'groups.csv',
				'sections.csv',
				'terms.csv',
				'user_observers.csv',
				'users.csv',
				'xlist.csv',
			].sort(),
		);
		// The enrollment filters were applied by Canvas.
		const rows = parseCsv(files['enrollments.csv']);
		const header = rows[0];
		const statusColumn = header.indexOf('status');
		const baseRoleColumn = header.indexOf('base_role_type');
		expect(baseRoleColumn).toBeGreaterThanOrEqual(0);
		expect(statusColumn).toBeGreaterThanOrEqual(0);
		expect(rows.length).toBeGreaterThan(10);
		const roles = new Set(rows.slice(1).map((row) => row[baseRoleColumn]));
		expect([...roles].sort()).toEqual(['StudentEnrollment', 'TeacherEnrollment']);
		const statuses = new Set(rows.slice(1).map((row) => row[statusColumn]));
		expect([...statuses].filter((status) => !['active', 'invited'].includes(status))).toEqual([]);
		// Only courses of the requested term.
		const courses = parseCsv(files['courses.csv']);
		const termColumn = courses[0].indexOf('canvas_term_id');
		expect(courses.length).toBeGreaterThan(1);
		expect(new Set(courses.slice(1).map((row) => row[termColumn]))).toEqual(new Set([fx('termId')]));
	});

	it('create: a single-file report is a plain CSV; SIS term IDs are accepted', async () => {
		const [report] = await runOk({
			resource: 'accountReport',
			operation: 'create',
			params: {
				accountId: root,
				reportType: 'provisioning_csv',
				additionalFields: { users: true, enrollment_term_id: `sis_term_id:${fx('termSisId')}`, skip_message: true },
			},
		});
		const id = remember(root, report);
		const finished = await waitForReport(root, 'provisioning_csv', id);
		expect(finished.status).toBe('complete');
		const attachment = finished.attachment as Json;
		expect(String(attachment.filename)).toMatch(/\.csv$/);
		const csv = (await download(String(attachment.url))).toString('utf8');
		expect(csv.split('\n')[0]).toContain('canvas_user_id');
		expect(csv.trim().split('\n').length).toBeGreaterThan(50);
	});

	it('create: date range, course and enrollment-state parameters (Students With No Submissions)', async () => {
		const [report] = await runOk({
			resource: 'accountReport',
			operation: 'create',
			params: {
				accountId: root,
				reportType: 'students_with_no_submissions_csv',
				additionalFields: {
					course_id: fx('courseId'),
					start_at: '2026-11-01T00:00:00Z',
					end_at: '2026-11-10T00:00:00Z',
					include_enrollment_state: true,
					enrollment_state: ['active', 'invited'],
					skip_message: true,
				},
			},
		});
		const id = remember(root, report);
		const stored = await canvas().get<Json>(`/api/v1/accounts/${root}/reports/students_with_no_submissions_csv/${id}`);
		expect(stored.parameters).toMatchObject({
			course_id: fx('courseId'),
			start_at: '2026-11-01T00:00:00Z',
			end_at: '2026-11-10T00:00:00Z',
			include_enrollment_state: true,
			enrollment_state: ['active', 'invited'],
			skip_message: true,
		});
		const finished = await waitForReport(root, 'students_with_no_submissions_csv', id);
		expect(finished.status).toBe('complete');
		const csv = (await download(String((finished.attachment as Json).url))).toString('utf8');
		const table = parseCsv(csv);
		const stateColumn = table[0].indexOf('enrollment state');
		expect(stateColumn).toBeGreaterThanOrEqual(0);
		expect(table.length).toBeGreaterThan(1);
		expect(table.slice(1).filter((row) => !['active', 'invited'].includes(row[stateColumn]))).toEqual([]);
	});

	it('create: the remaining parameters and free-form "Other Parameters" are stored as sent', async () => {
		const [outcomes] = await runOk({
			resource: 'accountReport',
			operation: 'create',
			params: {
				accountId: root,
				reportType: 'outcome_results_csv',
				additionalFields: { order: 'courses', include_deleted: true, enrollment_term_id: fx('termId') },
			},
		});
		remember(root, outcomes);
		expect(outcomes.parameters).toEqual({ order: 'courses', include_deleted: true, enrollment_term_id: fx('termId') });

		const [tokens] = await runOk({
			resource: 'accountReport',
			operation: 'create',
			params: {
				accountId: root,
				reportType: 'user_access_tokens_csv',
				additionalFields: { exclude_deleted_and_expired: true },
			},
		});
		remember(root, tokens);
		expect(tokens.parameters).toEqual({ exclude_deleted_and_expired: true });

		const [portfolios] = await runOk({
			resource: 'accountReport',
			operation: 'create',
			params: {
				accountId: root,
				reportType: 'eportfolio_report_csv',
				additionalFields: { no_enrollments: true, include_deleted: false },
			},
		});
		remember(root, portfolios);
		expect(portfolios.parameters).toEqual({ no_enrollments: true, include_deleted: false });

		// Text from the editor and an object from an expression both work; explicit fields are kept.
		const others = await runOk({
			resource: 'accountReport',
			operation: 'create',
			items: [{ extra: { course_id: Number(fx('courseId2')) } }],
			params: {
				accountId: root,
				reportType: 'last_user_access_csv',
				additionalFields: { include_deleted: true, extra_parameters: '={{ $json.extra }}' },
			},
		});
		remember(root, others[0]);
		expect(others[0].parameters).toEqual({ include_deleted: true, course_id: Number(fx('courseId2')) });

		const [fromText] = await runOk({
			resource: 'accountReport',
			operation: 'create',
			params: {
				accountId: root,
				reportType: 'zero_activity_csv',
				additionalFields: { extra_parameters: '{"start_at": "2026-10-01", "course_id": "' + fx('courseId') + '"}' },
			},
		});
		remember(root, fromText);
		expect(fromText.parameters).toEqual({ start_at: '2026-10-01', course_id: fx('courseId') });
	});

	it('create: without parameters the report runs with its defaults', async () => {
		const [report] = await runOk({
			resource: 'accountReport',
			operation: 'create',
			params: { accountId: sub, reportType: 'unpublished_courses_csv' },
		});
		const id = remember(sub, report);
		expect(report.parameters).toEqual({});
		const finished = await waitForReport(sub, 'unpublished_courses_csv', id);
		expect(finished.status).toBe('complete');
	});

	it('create: an unknown report type, an unknown term and a lesser persona are reported as errors', async () => {
		const unknownType = await runNode({
			resource: 'accountReport',
			operation: 'create',
			params: { accountId: root, reportType: 'no_such_report_csv', errorHandling: { onError: 'continueWithError' } },
		});
		expect(unknownType.success).toEqual([]);
		expect(unknownType.error[0]).toMatchObject({
			errorCode: 404,
			errorType: 'NOT_FOUND',
			resource: 'accountReport',
			operation: 'create',
		});

		const unknownTerm = await runNode({
			resource: 'accountReport',
			operation: 'create',
			params: {
				accountId: root,
				reportType: 'grade_export_csv',
				additionalFields: { enrollment_term_id: '99999999' },
				errorHandling: { onError: 'continueWithError' },
			},
		});
		expect(unknownTerm.error[0]).toMatchObject({ errorCode: 400, errorType: 'VALIDATION_ERROR' });
		expect(String(unknownTerm.error[0].errorMessage)).toContain("invalid enrollment_term_id '99999999'");

		const asTeacher = await runNode({
			resource: 'accountReport',
			operation: 'create',
			persona: 'teacher',
			params: { accountId: root, reportType: 'grade_export_csv', errorHandling: { onError: 'continueWithError' } },
		});
		expect(asTeacher.error[0].errorType).toBe('FORBIDDEN');
	});

	it('create: starting the same report again while it runs is a 409 conflict, not a second report', async () => {
		const parameters = { users: true, courses: true, sections: true, enrollments: true, groups: true, include_deleted: true };
		// Canvas refuses a second report only while the first is queued or running. On a small
		// database an idle job runner can finish the first before the second request arrives, and
		// both are then created: try again until the second one meets a report that is still on its way.
		let result: Awaited<ReturnType<typeof runNode>> | undefined;
		for (let attempt = 0; attempt < 6; attempt++) {
			const tried = await runNode({
				resource: 'accountReport',
				operation: 'create',
				items: [{ n: 1 }, { n: 2 }],
				params: {
					accountId: root,
					reportType: 'provisioning_csv',
					additionalFields: parameters,
					errorHandling: { onError: 'continueWithError' },
					batchProcessing: { mode: 'individual' },
					// The second request has to arrive while the first report is still being generated:
					// no waiting for the rate limit quota between the two.
					rateLimiting: { enabled: false },
				},
			});
			for (const report of tried.success) remember(root, report);
			if (tried.error.length > 0) {
				result = tried;
				break;
			}
			// Both were created: they are two reports of their own. Let them finish, then try again.
			expect(new Set(tried.success.map((r) => r.id)).size).toBe(2);
			for (const report of tried.success) await waitForReport(root, 'provisioning_csv', String(report.id));
		}
		if (!result) throw new Error('Canvas never met a running report in six attempts');
		expect(result.success).toHaveLength(1);
		const id = String(result.success[0].id);
		expect(result.error).toHaveLength(1);
		expect(result.error[0]).toMatchObject({
			errorCode: 409,
			errorType: 'CONFLICT',
			operation: 'create',
			originalItem: { n: 2 },
		});
		// Canvas answers the refusal with the report that is already running: a workflow can carry on with it.
		expect(result.error[0].responseBody).toMatchObject({ id: Number(id), report: 'provisioning_csv' });
		const reports = await canvas().getAll<Json>(`/api/v1/accounts/${root}/reports/provisioning_csv`);
		const sameParameters = reports.filter(
			(r) => (r.parameters as Json | null)?.groups === true && Number(r.id) >= Number(id),
		);
		expect(sameParameters.map((r) => r.id)).toEqual([Number(id)]);
		await waitForReport(root, 'provisioning_csv', id);
	});

	// ------------------------------------------------------- waitForCompletion

	it('waitForCompletion: returns the finished report with its file; giving up is reported as TIMEOUT', async () => {
		const [started] = await runOk({
			resource: 'accountReport',
			operation: 'create',
			params: { accountId: root, reportType: 'provisioning_csv', additionalFields: { users: true, courses: true, skip_message: true } },
		});
		const id = remember(root, started);
		expect(['created', 'running', 'compiling']).toContain(String(started.status));

		// Not enough time: the item fails with TIMEOUT, the report keeps running.
		const impatient = await runNode({
			resource: 'accountReport',
			operation: 'waitForCompletion',
			params: {
				accountId: root,
				reportType: 'provisioning_csv',
				reportId: id,
				pollInterval: 1,
				timeout: 0,
				errorHandling: { onError: 'continueWithError' },
			},
		});
		if (impatient.error.length > 0) {
			expect(impatient.error[0]).toMatchObject({ errorCode: 0, errorType: 'TIMEOUT', operation: 'waitForCompletion' });
			expect(String(impatient.error[0].errorMessage)).toContain('Still not finished after 0 seconds');
		} else {
			// The job was quicker than the first look.
			expect(impatient.success[0].status).toBe('complete');
		}

		const [finished] = await runOk({
			resource: 'accountReport',
			operation: 'waitForCompletion',
			params: { accountId: root, reportType: 'provisioning_csv', reportId: id, pollInterval: 2, timeout: 300 },
		});
		expect(finished).toMatchObject({ id: Number(id), status: 'complete', progress: 100 });
		const direct = await canvas().get<Json>(`/api/v1/accounts/${root}/reports/provisioning_csv/${id}`);
		expect((finished.attachment as Json).id).toBe((direct.attachment as Json).id);

		// Waiting for something that is already finished returns at once.
		const startedAt = Date.now();
		await runOk({
			resource: 'accountReport',
			operation: 'waitForCompletion',
			params: { accountId: root, reportType: 'provisioning_csv', reportId: id, pollInterval: 30 },
		});
		expect(Date.now() - startedAt).toBeLessThan(15_000);

		// Download File: the report's zip arrives as binary data, byte for byte what Canvas serves.
		const expected = await download(String((direct.attachment as Json).url));
		for (const operation of ['waitForCompletion', 'get']) {
			const withFile = await runNode({
				resource: 'accountReport',
				operation,
				params: { accountId: root, reportType: 'provisioning_csv', reportId: id, downloadFile: true, binaryPropertyName: 'report' },
				digestBinary: 'report',
			});
			expect(withFile.error, operation).toEqual([]);
			expect(withFile.success[0], operation).toMatchObject({ id: Number(id), status: 'complete' });
			expect(withFile.digests, operation).toEqual([
				{ ...digestOf(expected), fileName: (direct.attachment as Json).filename, mimeType: (direct.attachment as Json)['content-type'] },
			]);
		}
		expect(Object.keys(unzip(expected)).sort()).toEqual(['courses.csv', 'users.csv']);

		// A report without a file (aborted before it ran) comes back without one instead of failing.
		const aborted = await canvas().post<Json>(`/api/v1/accounts/${root}/reports/provisioning_csv`, {
			parameters: { users: true, groups: true, group_memberships: true, skip_message: true },
		});
		const abortedId = remember(root, aborted);
		await canvas().request('PUT', `/api/v1/accounts/${root}/reports/provisioning_csv/${abortedId}/abort`);
		const noFile = await runNode({
			resource: 'accountReport',
			operation: 'waitForCompletion',
			params: { accountId: root, reportType: 'provisioning_csv', reportId: abortedId, downloadFile: true, pollInterval: 2 },
			digestBinary: 'data',
		});
		expect(noFile.error).toEqual([]);
		if (noFile.success[0].status === 'aborted') {
			expect(noFile.digests).toEqual([null]);
		}
	});

	// --------------------------------------------------------------------- get

	it('get: returns the report with its file once complete; several items keep their pairing', async () => {
		const report = await canvas().post<Json>(`/api/v1/accounts/${root}/reports/unused_courses_csv`, {
			parameters: { enrollment_term_id: fx('pastTermId') },
		});
		const id = remember(root, report);
		const finished = await waitForReport(root, 'unused_courses_csv', id);
		const actual = await canvas().get<Json>(`/api/v1/accounts/${root}/reports/unused_courses_csv/${id}`);
		expect(finished).toMatchObject({
			id: Number(id),
			report: 'unused_courses_csv',
			status: 'complete',
			file_url: actual.file_url,
			created_at: actual.created_at,
			ended_at: actual.ended_at,
		});
		expect((finished.attachment as Json).id).toBe((actual.attachment as Json).id);

		const mixed = await runNode({
			resource: 'accountReport',
			operation: 'get',
			items: [{ id: Number(id) }, { id: 99999999 }, { id }],
			params: {
				accountId: root,
				reportType: 'unused_courses_csv',
				reportId: '={{ $json.id }}',
				errorHandling: { onError: 'continueWithError' },
			},
		});
		expect(mixed.success.map((r) => r.id)).toEqual([Number(id), Number(id)]);
		expect(mixed.rawSuccess.map((i) => (i.pairedItem as Json).item)).toEqual([0, 2]);
		expect(mixed.error[0]).toMatchObject({ errorCode: 404, errorType: 'NOT_FOUND', originalItem: { id: 99999999 } });
	});

	it('get: a report is only found under its own type', async () => {
		const report = createdReports.find((r) => r.type === 'unused_courses_csv')!;
		const result = await runNode({
			resource: 'accountReport',
			operation: 'get',
			params: {
				accountId: root,
				reportType: 'grade_export_csv',
				reportId: report.id,
				errorHandling: { onError: 'continueWithError' },
			},
		});
		expect(result.error[0]).toMatchObject({ errorCode: 404, errorType: 'NOT_FOUND' });
	});

	// ------------------------------------------------------------------ getAll

	it('getAll: lists the runs of one report type, newest first, across pages', async () => {
		// More runs than one default page; distinct parameters so Canvas does not answer 409.
		for (let i = 0; i < 12; i++) {
			const report = await canvas().post<Json>(`/api/v1/accounts/${sub}/reports/lti_report_csv`, {
				parameters: { battery_probe: `${Date.now()}-${i}` },
			});
			remember(sub, report);
		}
		const expected = await canvas().getAll<Json>(`/api/v1/accounts/${sub}/reports/lti_report_csv`);
		expect(expected.length).toBeGreaterThanOrEqual(12);

		const all = await runOk({
			resource: 'accountReport',
			operation: 'getAll',
			params: { accountId: sub, reportType: 'lti_report_csv', pagination: { returnAll: true } },
		});
		expect(all.map((r) => r.id)).toEqual(expected.map((r) => r.id));
		expect(ids(all)).toEqual([...ids(all)].sort((a, b) => a - b));
		expect(all.map((r) => r.id)).toEqual([...all.map((r) => Number(r.id))].sort((a, b) => b - a));
		expect(all.every((r) => r.report === 'lti_report_csv')).toBe(true);

		const defaults = await runOk({
			resource: 'accountReport',
			operation: 'getAll',
			params: { accountId: sub, reportType: 'lti_report_csv' },
		});
		expect(defaults).toHaveLength(Math.min(expected.length, 50));

		const paged = await runOk({
			resource: 'accountReport',
			operation: 'getAll',
			params: { accountId: sub, reportType: 'lti_report_csv', pagination: { perPage: 5, maxPages: 2 } },
		});
		expect(paged).toHaveLength(10);
		expect(new Set(ids(paged)).size).toBe(10);
	});

	it('getAll: a report type that never ran yields no items', async () => {
		const result = await runNode({
			resource: 'accountReport',
			operation: 'getAll',
			params: { accountId: fx('deepSubAccountId'), reportType: 'mgp_grade_export_csv' },
		});
		expect(result.ok).toBe(true);
		expect(result.success).toEqual([]);
	});

	// ------------------------------------------------------------------- abort

	it('abort: stops a running report without deleting it', async () => {
		const report = await canvas().post<Json>(`/api/v1/accounts/${root}/reports/provisioning_csv`, {
			parameters: {
				users: true,
				accounts: true,
				terms: true,
				courses: true,
				sections: true,
				enrollments: true,
				groups: true,
				group_membership: true,
				include_deleted: true,
				battery_probe: `abort-${Date.now()}`,
			},
		});
		const id = remember(root, report);
		const [aborted] = await runOk({
			resource: 'accountReport',
			operation: 'abort',
			params: { accountId: root, reportType: 'provisioning_csv', reportId: id },
		});
		expect(aborted).toMatchObject({ id: Number(id), status: 'aborted' });

		// Still there (the old implementation sent DELETE, which removed the report).
		const actual = await canvas().get<Json>(`/api/v1/accounts/${root}/reports/provisioning_csv/${id}`);
		expect(actual.status).toBe('aborted');
		const listed = await canvas().getAll<Json>(`/api/v1/accounts/${root}/reports/provisioning_csv`);
		expect(ids(listed)).toContain(Number(id));

		// A report that is no longer running cannot be aborted.
		const again = await runNode({
			resource: 'accountReport',
			operation: 'abort',
			params: {
				accountId: root,
				reportType: 'provisioning_csv',
				reportId: id,
				errorHandling: { onError: 'continueWithError' },
			},
		});
		expect(again.error[0]).toMatchObject({ errorCode: 404, errorType: 'NOT_FOUND', operation: 'abort' });
	});

	// ------------------------------------------------------------------ delete

	it('delete: removes a finished report', async () => {
		const report = await canvas().post<Json>(`/api/v1/accounts/${sub}/reports/public_courses_csv`, {
			parameters: { battery_probe: `delete-${Date.now()}` },
		});
		const id = String(report.id);
		await waitForReport(sub, 'public_courses_csv', id);

		const [deleted] = await runOk({
			resource: 'accountReport',
			operation: 'delete',
			params: { accountId: sub, reportType: 'public_courses_csv', reportId: id },
		});
		expect(deleted).toMatchObject({ id: Number(id), status: 'deleted' });
		const after = await canvas().request('GET', `/api/v1/accounts/${sub}/reports/public_courses_csv/${id}`);
		expect(after.status).toBe(404);
		const listed = await canvas().getAll<Json>(`/api/v1/accounts/${sub}/reports/public_courses_csv`);
		expect(ids(listed)).not.toContain(Number(id));

		const again = await runNode({
			resource: 'accountReport',
			operation: 'delete',
			params: {
				accountId: sub,
				reportType: 'public_courses_csv',
				reportId: id,
				errorHandling: { onError: 'continueWithError' },
			},
		});
		expect(again.error[0]).toMatchObject({ errorCode: 404, errorType: 'NOT_FOUND', operation: 'delete' });
	});
});
